BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT jsonb_build_object('n',count(*),'human',count(*) FILTER(WHERE summary_json->'request_origin'->>'kind'='human'),'ai',count(*) FILTER(WHERE summary_json->'request_origin'->>'kind'='ai'),'unknown',count(*) FILTER(WHERE summary_json->'request_origin'->>'kind'='unknown'),'missing',count(*) FILTER(WHERE NOT(summary_json ? 'request_origin')),'linked',count(*) FILTER(WHERE usage_log_id IS NOT NULL),'pending',count(*) FILTER(WHERE usage_link_version<>usage_link_checked_version),'min_version',min((summary_json->'request_origin'->>'version')::int),'max_version',max((summary_json->'request_origin'->>'version')::int)) FROM token_analysis_request_summaries WHERE event_time >= TIMESTAMPTZ '2026-10-26T09:00:00+08:00' AND event_time < TIMESTAMPTZ '2026-10-27T09:00:00+08:00';
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT jsonb_build_object('other_audit_connections',count(*),'other_audit_open_transactions',count(*) FILTER(WHERE xact_start IS NOT NULL)) FROM pg_stat_activity WHERE application_name='token_origin_v2_evidence_20261027' AND pid<>pg_backend_pid();
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);
